                krsort($args);
                krsort($emptyArguments);

                if ($argCount > 0) {
                    $args = $this->addDefaultArgumentValues($functionCall, $args, $emptyArguments);
                }

                if (($passByReference) && ($argCount == 0)) {
                    $args[] = $cellID;
                    $argArrayVals[] = $this->showValue($cellID);
                }

                if ($functionName !== 'MKMATRIX') {
